//! `smelt clean`: remove the manifest's `output.target` (see `specs/cli.md`).
//!
//! Files smelt writes are removed without asking: generated `.rs` files (they
//! start with smelt's `@generated` header), the manifest and lock file and the
//! two sidecars of the generated crate, the specialization artifacts a build
//! publishes under `.smelt/specialization/` (an artifact whose cache key is its
//! file name), and Cargo's `target/` inside it.
//! Anything else is someone's file, so removing it needs confirmation or
//! `--force`. A target that is the project directory, or holds it, is never
//! removed.

use std::{
    fs, io,
    path::{Path, PathBuf},
};

use crate::config::Config;
use crate::source_files::resolve_manifest_path;

/// First line of every generated Rust file.
const GENERATED_HEADER: &str = "// @generated by smelt.";

/// Non-Rust files of a generated crate, by name.
const GENERATED_FILES: [&str; 4] = [
    "Cargo.toml",
    "Cargo.lock",
    "smelt-erasure.json",
    "smelt-typedness.json",
];

/// What a clean did.
#[derive(Debug, PartialEq, Eq)]
pub(crate) enum Cleaned {
    /// The target did not exist.
    Nothing(PathBuf),
    /// The target was removed.
    Removed(PathBuf),
}

/// Removes the output target of the manifest at `manifest_path`.
///
/// `confirm` is asked, with the files smelt did not write, before any of them
/// is removed; `force` skips it. Returns an error, removing nothing, when the
/// target holds the project or when `confirm` declines.
pub(crate) fn clean(
    config: &Config,
    manifest_path: &Path,
    force: bool,
    confirm: impl FnOnce(&[PathBuf]) -> io::Result<bool>,
) -> Result<Cleaned, String> {
    let manifest_dir = manifest_path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    let target = resolve_manifest_path(manifest_dir, config.output_target());
    if !target.exists() {
        return Ok(Cleaned::Nothing(target));
    }
    let failed = |error: io::Error| format!("cannot clean `{}`: {error}", target.display());
    let project = fs::canonicalize(manifest_dir).map_err(failed)?;
    if project.starts_with(fs::canonicalize(&target).map_err(failed)?) {
        return Err(format!(
            "refusing to remove `{}`: output.target holds the project itself",
            target.display()
        ));
    }
    if !target.is_dir() {
        return Err(format!(
            "refusing to remove `{}`: it is not a directory",
            target.display()
        ));
    }
    let foreign = foreign_files(&target).map_err(failed)?;
    if !foreign.is_empty() && !force && !confirm(&foreign).map_err(failed)? {
        return Err(format!("left `{}` in place", target.display()));
    }
    fs::remove_dir_all(&target).map_err(failed)?;
    Ok(Cleaned::Removed(target))
}

/// Every kind of file a build writes into its output target.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum OutputFile {
    /// A crate file named in [`GENERATED_FILES`], at the target's root.
    CrateFile,
    /// A Rust source starting with [`GENERATED_HEADER`].
    RustSource,
    /// A specialization artifact the build published for its package.
    SpecializationArtifact,
}

/// Files under `directory` that smelt did not write, sorted.
fn foreign_files(directory: &Path) -> io::Result<Vec<PathBuf>> {
    let artifacts = smelt_specialize::SpecializationArtifactStore::new(
        directory.join(".smelt").join("specialization"),
    );
    let mut foreign = Vec::new();
    let mut pending = vec![directory.to_path_buf()];
    while let Some(current) = pending.pop() {
        for entry in fs::read_dir(&current)? {
            let path = entry?.path();
            if path.is_dir() {
                if !(current == directory && path.file_name().is_some_and(|name| name == "target"))
                {
                    pending.push(path);
                }
            } else if output_file(&path, current == directory, &artifacts).is_none() {
                foreign.push(path);
            }
        }
    }
    foreign.sort();
    Ok(foreign)
}

/// Which file of a build `path` is, or `None` when smelt did not write it;
/// `at_root` says it sits directly in the target, and `artifacts` is the
/// target's specialization store. An unreadable file counts as foreign, so it
/// is never removed unasked.
fn output_file(
    path: &Path,
    at_root: bool,
    artifacts: &smelt_specialize::SpecializationArtifactStore,
) -> Option<OutputFile> {
    let name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or_default();
    if at_root && GENERATED_FILES.contains(&name) {
        return Some(OutputFile::CrateFile);
    }
    if path.extension().is_some_and(|extension| extension == "rs")
        && fs::read_to_string(path).is_ok_and(|text| text.starts_with(GENERATED_HEADER))
    {
        return Some(OutputFile::RustSource);
    }
    artifacts
        .wrote(path)
        .then_some(OutputFile::SpecializationArtifact)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Generated files are recognized by header or name; anything else is not.
    #[test]
    fn foreign_files_are_what_smelt_did_not_write() -> Result<(), String> {
        let directory = tempfile::tempdir().map_err(|error| error.to_string())?;
        let root = directory.path();
        build_fixture(root).map_err(|error| error.to_string())?;
        let clean = foreign_files(root).map_err(|error| error.to_string())?;
        if !clean.is_empty() {
            return Err(format!("generated files counted as foreign: {clean:?}"));
        }
        for (file, text) in [
            ("src/hand.rs", "fn main() {}\n"),
            ("notes.txt", "mine"),
            ("src/Cargo.toml", ""),
        ] {
            fs::write(root.join(file), text).map_err(|error| error.to_string())?;
        }
        let foreign = foreign_files(root).map_err(|error| error.to_string())?;
        let expected = vec![
            root.join("notes.txt"),
            root.join("src/Cargo.toml"),
            root.join("src/hand.rs"),
        ];
        if foreign == expected {
            return Ok(());
        }
        Err(format!("foreign files {foreign:?}, expected {expected:?}"))
    }

    /// A target holding only generated files, a published specialization
    /// artifact among them.
    fn build_fixture(root: &Path) -> io::Result<()> {
        fs::create_dir_all(root.join("src"))?;
        fs::create_dir_all(root.join("target/debug"))?;
        fs::write(root.join("Cargo.toml"), "[package]\n")?;
        fs::write(
            root.join("src/main.rs"),
            "// @generated by smelt. Do not edit by hand.\n",
        )?;
        fs::write(root.join("target/debug/app"), "")?;
        let store =
            smelt_specialize::SpecializationArtifactStore::new(root.join(".smelt/specialization"));
        let project = smelt_specialize::ProjectRoot::new(root)?;
        let manifest = artifact_manifest();
        let key = smelt_specialize::SpecializationCacheKey::compute(
            &smelt_specialize::CacheKeyInput::new(
                manifest.language,
                manifest.host_runtime_version.clone(),
                manifest.hashes.clone(),
                &manifest.sandbox_policy,
                &project,
            ),
        )
        .map_err(io::Error::other)?;
        store
            .store(&key, &manifest)
            .map_err(|error| io::Error::other(format!("{error:?}")))?;
        Ok(())
    }

    /// An empty, valid Python specialization manifest.
    fn artifact_manifest() -> smelt_specialize::SpecializationManifest {
        smelt_specialize::SpecializationManifest {
            smelt_version: "test".to_owned(),
            schema_version: smelt_specialize::MANIFEST_SCHEMA_VERSION,
            language: smelt_specialize::HostLanguage::Python,
            host_runtime_version: "3".to_owned(),
            hashes: smelt_specialize::HashInputs {
                source: String::new(),
                dependencies: String::new(),
                lockfile: String::new(),
                environment: String::new(),
                policy: String::new(),
                callable_provenance: String::new(),
            },
            sandbox_policy: smelt_specialize::SandboxPolicyRecord {
                backend: "none".to_owned(),
                network: false,
                read_only_roots: Vec::new(),
                writable_roots: Vec::new(),
                environment: std::collections::BTreeMap::new(),
                wall_time_ms: 1,
                cpu_time_ms: 1,
                memory_bytes: 1,
                process_limit: 1,
                output_bytes: 1,
                subprocesses: false,
                native_extensions: Vec::new(),
            },
            modules: Vec::new(),
            values: smelt_specialize::ValueGraph { nodes: Vec::new() },
            effects: Vec::new(),
            required_adapters: Vec::new(),
        }
    }

    /// A file under `.smelt/specialization` that is not an artifact of its
    /// name is someone's.
    #[test]
    fn a_stray_file_beside_the_artifacts_is_foreign() -> Result<(), String> {
        let directory = tempfile::tempdir().map_err(|error| error.to_string())?;
        let root = directory.path();
        build_fixture(root).map_err(|error| error.to_string())?;
        let stray = root.join(".smelt/specialization/python/notes.json");
        fs::write(&stray, "{}").map_err(|error| error.to_string())?;
        let foreign = foreign_files(root).map_err(|error| error.to_string())?;
        if foreign == vec![stray.clone()] {
            return Ok(());
        }
        Err(format!(
            "foreign files {foreign:?}, expected only {stray:?}"
        ))
    }
}
